content.text:
The evidence points to a single fault, a network partition between ts-seat-service and ts-config-service, which then backs up through the travel and route-planning tiers to the UI.

```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "network_partition",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, count(*) n, sum(CASE WHEN s.span_id IS NULL THEN 1 ELSE 0 END) no_child_server, round(avg(c.duration)/1e6,1) avg_ms, round(max(c.duration)/1e6,1) max_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.attr_span_kind='Server' WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' AND c.span_name='GET' GROUP BY 1,2",
          "claim": "Seat's outgoing GET calls take about 130s, all end in error, and none reach a callee server span."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, count(*) n FROM abnormal_traces WHERE service_name='ts-config-service' AND span_name LIKE 'GET /api/v1/configservice/configs/%' UNION ALL SELECT 'nrm', count(*) FROM normal_traces WHERE service_name='ts-config-service' AND span_name LIKE 'GET /api/v1/configservice/configs/%'",
          "claim": "Config's configName GET endpoint, called only by seat, drops from about 598 spans in normal to zero in abnormal."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' src, attr_k8s_pod_name pod, metric, count(*) n, round(min(value),2) mn, round(max(value),2) mx FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-seat%' AND metric IN ('k8s.container.restarts','k8s.container.ready') GROUP BY 1,2,3",
          "claim": "Seat pod stays ready with zero restarts during the abnormal window, so the fault is not a pod restart."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.duration > 10000000000 THEN 1 ELSE 0 END) over10s, round(avg(c.duration)/1e6,1) c_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name IN ('ts-travel-service','ts-travel2-service') AND s.service_name='ts-seat-service' GROUP BY 1,2",
          "claim": "Travel and travel2 calls into seat are mostly over 10 seconds in the abnormal window, mirroring seat's hung calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.duration > 10000000000 THEN 1 ELSE 0 END) over10s, round(avg(c.duration)/1e6,1) c_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel-service' AND s.service_name='ts-seat-service' GROUP BY 1,2",
          "claim": "Travel's POST calls to seat take about 130 seconds, with two over 10 seconds, while seat is blocked."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.duration > 10000000000 THEN 1 ELSE 0 END) over10s, round(avg(c.duration)/1e6,1) c_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel2-service' AND s.service_name='ts-seat-service' GROUP BY 1,2",
          "claim": "Travel2's call into seat takes about 130 seconds and exceeds 10 seconds, the same hang seen in travel."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.duration > 10000000000 THEN 1 ELSE 0 END) over10s, round(avg(c.duration)/1e6,1) c_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' AND s.service_name IN ('ts-travel2-service','ts-travel-service') GROUP BY 1,2",
          "claim": "Route-plan's calls to travel2 and travel run for seconds, with several over 10 seconds, and its server errors rise."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.duration > 10000000000 THEN 1 ELSE 0 END) over10s, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) srv_err, round(avg(c.duration)/1e6,1) c_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "Travel-plan's calls to route-plan average 16.8 seconds, with five over 10 seconds and four server errors."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%travelPlan%' GROUP BY 1,2 ORDER BY 3 DESC",
          "claim": "UI requests to travel-plan endpoints take about 2.5 to 4.3 seconds on average, with maxima near 20 seconds."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%trips/left%' GROUP BY 1,2 ORDER BY 3 DESC",
          "claim": "UI calls to travel's trips/left endpoint average about 1 second, with maxima near 20 seconds, during the seat hang."
        }
      ]
    }
  ]
}
```

